  "minimal-polish.lino": "natural:\n  id: minimal-polish\n  label: 'Minimal Polish (NSM semantic primes)'\n  extends: polish\n  profile: minimal-english\n  source: 'https://en.wikipedia.org/wiki/Natural_semantic_metalanguage'\n  true: prawda\n  false: nieprawda\n  templates:\n    function: 'Tak ktoś robi {name} z {parameters}'\n    function-without-parameters: 'Tak ktoś robi {name}'\n    declare: 'Jest {name}, to jest {value}'\n    assign: 'Po tym {name} jest {value}'\n    print-line: 'Powiedzieć {value} w jednej linii'\n    print: 'Powiedzieć {value}'\n    return-value: 'Odpowiedzią jest {value}'\n    return: 'Przestać tutaj'\n    nothing: 'Nic nie robić'\n    evaluate: 'Zrobić {expression}'\n    if: 'Jeżeli {condition}, zrobić to'\n    else-if: 'Jeżeli nie, jeżeli {condition}, zrobić to'\n    else: 'Jeżeli nie, zrobić to'\n    while: 'Kiedy {condition}, robić to wiele razy'\n    for: 'Dla wszystkich {variable} od {start} do {last}, zrobić to'\n    call-without-arguments: '{callee} ( )'\n    join: '{left} potem {right}'\n    negate: 'przeciwieństwo {operand}'\n    equal: '{left} jest tym samym co {right}'\n    not-equal: '{left} nie jest tym samym co {right}'\n    less: '{left} jest mniej niż {right}'\n    less-or-equal: '{left} nie jest więcej niż {right}'\n    greater: '{left} jest więcej niż {right}'\n    greater-or-equal: '{left} nie jest mniej niż {right}'\n    array: 'te rzeczy ({elements})'\n    new-array: '{length} rzeczy jak {fill}'\n    element: 'część {index} z {array}'\n    length: 'ile części ma {array}'\n    set-element: 'Po tym część {index} z {name} jest {value}'\n  rules:\n    primes: polish\n    extra-words: tak z w jednej linii odpowiedzią przestać nic zrobić robić wiele razy dla od do potem lub i przeciwieństwo tym samym co niż mniej plus minus podzielone przez modulo prawda nieprawda te rzeczy ile części ma\n",
